@startuml
class House {
  +address : string
  +buildingMaterial : string
}

class Basement {
  +name : string
  +size : string
}

class EarthBasement extends Basement {
  +humidityLevel : float
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  +hasOwnGarden : boolean
  +windowsCount : int
}

class Carport {
  +isDoubleCarport : boolean
  +hasFlatRoof : boolean
}

class Garage {
  +hasAutomaticGarageDoor : boolean
}

class Company {
  +name : string
  +address : string
}

class JobLog {
  +hours : float
  +agreedPrice : double
}

House "0..1" -- "0..1" Basement : has
SemiDetachedHouse "1" -- "2" Carport : has
SemiDetachedHouse "1" -- "0..1" Garage : has
House "1" -- "*" Company : is serviced by
Company "1" -- "*" JobLog : performs
House "1" -- "*" JobLog : has
JobLog "*" -- "1" Company : is performed by
@enduml

